{
  "name": "Huber Petite Fleur循环冷却器",
  "name_en": "Huber Petite Fleur recirculating chiller",
  "manufacturer": "Huber",
  "description": "这是一台台式循环冷却与恒温控制设备，通过循环传热液体为浴槽或外部实验装置提供稳定的温度控制。实验中常用于维持设定温度、监测浴液温度，并按设定程序或斜坡方式改变温度。",
  "description_en": "A benchtop recirculating chiller and temperature-control unit that circulates heat-transfer fluid to provide stable temperature control for a bath or external laboratory equipment. It is commonly used in labs to maintain a set temperature, monitor bath temperature, and change temperature using ramps or control programs.",
  "tag_hints": [
    "recirculating chiller",
    "liquid temperature control",
    "circulating bath",
    "temperature ramping",
    "process thermostat",
    "pump circulation"
  ],
  "actions": [
    {
      "action_name": "auto-initialize_device",
      "description": "初始化冷却器（该设备通常无需专门初始化）",
      "description_en": "Initialize the chiller (this device typically does not require dedicated initialization)."
    },
    {
      "action_name": "auto-is_connected",
      "description": "检查冷却器是否在线并有响应",
      "description_en": "Check whether the chiller is connected and responding."
    },
    {
      "action_name": "auto-is_idle",
      "description": "检查冷却器是否处于空闲或未运行状态",
      "description_en": "Check whether the chiller is idle or not running."
    },
    {
      "action_name": "auto-clear_errors",
      "description": "清除设备错误状态",
      "description_en": "Clear device error states."
    },
    {
      "action_name": "auto-check_errors",
      "description": "检查设备错误状态",
      "description_en": "Check device error states."
    },
    {
      "action_name": "auto-temp_transform",
      "description": "将温度值转换为设备使用的数值格式",
      "description_en": "Convert a temperature value into the numeric format used by the device."
    },
    {
      "action_name": "auto-start_temperature_regulation",
      "description": "启动循环与温度调节",
      "description_en": "Start circulation and temperature regulation."
    },
    {
      "action_name": "auto-stop_temperature_regulation",
      "description": "停止循环与温度调节",
      "description_en": "Stop circulation and temperature regulation."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置目标温度",
      "description_en": "Set the target temperature."
    },
    {
      "action_name": "auto-ramp_temperature",
      "description": "设定温度斜坡，在指定时间内升降至目标温度",
      "description_en": "Define a temperature ramp to reach the target temperature over a specified time."
    },
    {
      "action_name": "auto-start_temp_ctrl",
      "description": "启动预设的温度控制程序",
      "description_en": "Start a predefined temperature control program."
    },
    {
      "action_name": "auto-interpret_status",
      "description": "解释设备状态信息",
      "description_en": "Interpret device status information."
    },
    {
      "action_name": "auto-set_circulator_control",
      "description": "设置循环器控制模式",
      "description_en": "Set the circulator control mode."
    }
  ]
}

